using System.Text.Json;
using LexiSharp.Ranking;
using Xunit;

namespace LexiSharp.Tests;

/// <summary>
/// Differential tests for the fitted score calibrators against scikit-learn.
/// </summary>
/// <remarks>
/// The fixture is generated by <c>scripts/generate-calibration-fixture.py</c> and checked in.
/// Isotonic is compared at the fitted grid to a PAVA fit; Platt is compared to an unregularised
/// logistic regression. The tolerances leave room for the shipped Platt solver (fixed-step
/// gradient descent plus a 100-point lookup table) rather than pretending it is a convex solver.
/// </remarks>
public class CalibrationDifferentialTests
{
    private sealed class Fixture
    {
        public string Source { get; init; } = string.Empty;

        public string Version { get; init; } = string.Empty;

        public List<Case> Cases { get; init; } = [];
    }

    private sealed class Case
    {
        public string Name { get; init; } = string.Empty;

        public List<Example> Examples { get; init; } = [];

        public double[] Grid { get; init; } = [];

        public double[] ExpectedIsotonic { get; init; } = [];

        public double[] ExpectedPlatt { get; init; } = [];
    }

    private sealed class Example
    {
        public double Score { get; init; }

        public bool Correct { get; init; }
    }

    [Fact]
    public void IsotonicAndPlatt_MatchScikitLearn()
    {
        string path = Path.Combine(
            AppContext.BaseDirectory, "TestData", "calibration-scipy.json");

        Fixture fixture = JsonSerializer.Deserialize<Fixture>(
            File.ReadAllText(path),
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
            ?? throw new InvalidOperationException("The calibration fixture is empty.");

        Assert.Equal("scikit-learn", fixture.Source);
        Assert.NotEmpty(fixture.Version);
        Assert.NotEmpty(fixture.Cases);

        foreach (Case test in fixture.Cases)
        {
            var examples = test.Examples
                .Select(example => (example.Score, example.Correct))
                .ToList();

            CalibratedScoreConfidence isotonic = CalibratedScoreConfidence.Fit(
                examples, CalibrationMethod.IsotonicRegression);
            CalibratedScoreConfidence platt = CalibratedScoreConfidence.Fit(
                examples, CalibrationMethod.PlattScaling);

            double maximumIsotonicError = 0;
            double maximumPlattError = 0;
            double previousIsotonic = double.NegativeInfinity;
            double previousPlatt = double.NegativeInfinity;

            for (int i = 0; i < test.Grid.Length; i++)
            {
                double score = test.Grid[i];
                double actualIsotonic = isotonic.PredictProba(score);
                double actualPlatt = platt.PredictProba(score);

                maximumIsotonicError = Math.Max(
                    maximumIsotonicError, Math.Abs(actualIsotonic - test.ExpectedIsotonic[i]));
                maximumPlattError = Math.Max(
                    maximumPlattError, Math.Abs(actualPlatt - test.ExpectedPlatt[i]));

                Assert.True(
                    actualIsotonic >= previousIsotonic - 1e-12,
                    $"{test.Name}: isotonic is not monotonic at score {score:R}");
                Assert.True(
                    actualPlatt >= previousPlatt - 1e-12,
                    $"{test.Name}: Platt is not monotonic at score {score:R}");

                previousIsotonic = actualIsotonic;
                previousPlatt = actualPlatt;
            }

            Assert.True(
                maximumIsotonicError <= 0.05,
                $"{test.Name}: isotonic maximum error {maximumIsotonicError:R}");
            Assert.True(
                maximumPlattError <= 0.15,
                $"{test.Name}: Platt maximum error {maximumPlattError:R}");
        }
    }
}
